def clean(words):
    return [w.strip().lower() for w in words if len(w.strip()) > 2]

print(clean([" Hi ", "Go", "Python ", "  "]))

def count_repeats(words):
    seen = {}
    repeats = 0
    for w in words:
        seen[w] = seen.get(w, 0) + 1
    for w in seen:
        if seen[w] == 1:
            repeats += 1
    return repeats

def process(nums):
    total, count = 0, 0
    for n in nums:
        if n > 0:
            total += n
            count += 1
    return total / count if count else 0

print(process([-2, 4, -1, 6, 8]))
